@router.post("/api/v1/backups/schedules/{schedule_id}/trigger-now")
def trigger_backup_schedule_now(
    schedule_id: int,
    scheduler: AsyncIOScheduler = Depends(get_scheduler),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    schedule = db.query(BackupSchedule).filter(
        BackupSchedule.id == schedule_id,
        BackupSchedule.organization_id == current_user.organization_id
    ).first()
    if not schedule:
        raise HTTPException(status_code=404, detail="Schedule not found or unauthorized")
    scheduler.add_job(
        run_database_backup,
        args=[schedule.database_uri, schedule.target_storage_bucket],
        id=f"manual_run_{schedule.id}_{uuid.uuid4().hex[:6]}"
    )
    return {"status": "backup_job_dispatched", "schedule_id": schedule_id}
